#!/usr/bin/env node
// scripts/send-pick-a-plan-preview.js
// One-off test send of the 'pick a plan' reminder email, upgraded with two
// real app screenshots (Available Slots + a confirmed booking card), to
// verify how it actually renders before this replaces the plain-text
// version in billing.routes.ts. Self-contained on purpose (no app imports)
// so it can be curled straight into a shell with no checkout needed.
// Safe to delete after the test — not wired into any route or cron.
//
// Usage: RESEND_API_KEY and RESEND_FROM_EMAIL already live in this
// environment (Render), so just run:
//   node scripts/send-pick-a-plan-preview.js [recipient-email]

const to = process.argv[2] || 'pdrogero@gmail.com';
const appUrl = process.env.APP_URL || 'https://arrowheadaccess.com';

const SLOTS_B64 = '';
const CONFIRMED_B64 = '';

const emailLogoHeader = () => `<div style="text-align:center;padding:8px 0 20px;">
  <a href="${appUrl}/app.html" style="text-decoration:none;">
    <img src="${appUrl}/icon-192.png" width="44" height="44" alt="Arrowhead Access" style="border-radius:10px;display:inline-block;vertical-align:middle;">
    <span style="font-size:19px;font-weight:700;color:#16241F;vertical-align:middle;margin-left:10px;">Arrowhead Access</span>
  </a>
</div>`;
const emailLoginButton = (label) => `<p><a href="${appUrl}/app.html" style="display:inline-block;background:#2E6F5E;color:#fff;text-decoration:none;padding:11px 22px;border-radius:8px;font-weight:600;">${label}</a></p>`;
const shotFrame = (b64, alt) => `
  <div style="border:1px solid #E2E1D8;border-radius:12px;overflow:hidden;margin:16px 0 6px;">
    <div style="padding:9px 12px;background:#F5F5F0;border-bottom:1px solid #E2E1D8;font-size:0;">
      <span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:#D8D7CC;margin-right:6px;"></span>
      <span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:#D8D7CC;margin-right:6px;"></span>
      <span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:#D8D7CC;"></span>
    </div>
    <img src="data:image/png;base64,${b64}" alt="${alt}" width="560" style="display:block;width:100%;height:auto;">
  </div>`;

const name = 'there';
const html = `${emailLogoHeader()}
<p>Hi ${name},</p>
<p>You signed up for Arrowhead Access, but haven't started your 14-day free trial yet. Here's what's open at offices near you right now:</p>
${shotFrame(SLOTS_B64, 'Open visit slots waiting to be claimed')}
<p style="text-align:center;font-size:11.5px;color:#5B6760;margin:6px 0 20px;">A live look at your Available Slots screen -- these are real open times right now.</p>
<p>Claiming one (or messaging an office) needs a plan picked first. It only takes a minute, and you won't be charged until the trial ends.</p>
<p>And once an office accepts your request, here's what you get:</p>
${shotFrame(CONFIRMED_B64, 'A confirmed lunch booking, with calendar sync, messaging, attendance tracking, and expense logging')}
<p style="text-align:center;font-size:11.5px;color:#5B6760;margin:6px 0 20px;">Calendar sync, direct messaging, attendance tracking, expense logging, and ratings -- all in one place once you're confirmed.</p>
${emailLoginButton('Choose your plan')}
<p style="font-size:12.5px;color:#5B6760;margin-top:18px;border-top:1px solid #E2E1D8;padding-top:16px;">TEST SEND -- this is a preview of an upgraded version of the no-plan reminder email, not a live reminder about your own account.</p>
`;

async function main() {
  const apiKey = process.env.RESEND_API_KEY;
  if (!apiKey) {
    console.error('RESEND_API_KEY is not set in this shell -- nothing to send with.');
    process.exit(1);
  }
  const from = process.env.RESEND_FROM_EMAIL || 'Arrowhead Access <onboarding@resend.dev>';
  const res = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ from, to, subject: '[TEST] Your free trial is waiting on Arrowhead Access', html }),
  });
  const body = await res.text();
  if (!res.ok) {
    console.error('Send failed:', res.status, body);
    process.exit(1);
  }
  console.log('Sent to', to, '-- Resend response:', body);
}

main();
